    "modules.active": "Ativo",
    "modules.admin_only": "Apenas administradores",
    "modules.admin_only_modules": "Apenas os administradores podem ativar ou desativar módulos do sistema.",
    "modules.system_admin_only_hint": "Apenas os administradores podem ativar ou desativar módulos do sistema.",
