    "safety.incident_create_failed": "Falha ao reportar o incidente",
    "safety.incident_created": "Incidente reportado com sucesso",
    "safety.incident_desc_placeholder": "Descreva o que aconteceu...",
    "safety.incident_type_environmental": "Derrame ou emissão",
